def _build_category_map() -> list[dict[str, str]]:
    """Project the flat inventory into the base spider's category schema."""
    categories: list[dict[str, str]] = []
    seen: set[str] = set()
    for entry in BACKCOUNTRY_CATEGORY_INVENTORY:
        slug = entry["slug"]
        if slug in seen:
            continue
        seen.add(slug)
        categories.append({"category": slug, "url": entry["url"]})
    return categories


def _build_slug_labels() -> dict[str, dict[str, str]]:
    """Map each slug to its department/section/category labels."""
    return {entry["slug"]: entry for entry in BACKCOUNTRY_CATEGORY_INVENTORY}


# ``categories`` entries for BaseListingSpider ({"category": ..., "url": ...}).
BACKCOUNTRY_CATEGORIES = _build_category_map()

# Slug -> {"department", "section", "name", "url", "category_id"} for item
# labelling, so every emitted product can report where it was listed.
BACKCOUNTRY_SLUG_LABELS = _build_slug_labels()
